import React from 'react'
import { useState } from 'react';
import axios from 'axios';

function Login() {
    const [email,setEmail] = useState('');
    const [password,setPassword] = useState('');

    const onSubmit = async (e)=>{
        e.preventDefault();
        const loginDetails = {email, password};
        try{
            const response = await axios.post("http://localhost:8080/user/login", loginDetails);
            alert("Login successful");
            // You can store the user ID or token in localStorage or context for further use
            console.log("User ID:", response.data.id);
            window.location.href = ("/");
        }catch(error){
            alert("Login failed: " + error.response.data.message);
        }
    }
  return (
    <div>
      <h1>Login</h1>
      <form onSubmit={(e) => onSubmit(e)}>

        <label htmlFor="email">email</label><br />
        <input type="email" id="email" name="email" value={email} onChange={(e) => onInputChange(e)} required /><br />

        <label htmlFor="password">password</label><br />
        <input type="password" id="password" name="password" value={password} onChange={(e) => onInputChange(e)} required /><br />

        <button type="submit" className="fom_btn">login</button>
      </form>
    </div>
  )
}

export default Login
